//! Closed BQ088: bounded, optional repetitions of the original targeted process.
use crate::{catalog,engine::RuleResult,model::*,rules::*};
use serde::{Serialize,Deserialize};
use std::collections::BTreeSet;
pub(crate) const ID:&str="BQ088";
pub(crate) const TOKEN:&str="TK001";
pub(crate) const KEY:&str="bq088-leak";
#[derive(Clone,Debug,Serialize,Deserialize)]
pub enum Program {Start{limit:Option<u32>,round:u32},Mill,Generate,Seal,Repeat}
#[derive(Clone,Debug,Serialize,Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Continuation {pub turn:u32,pub frame:ResolutionFrame}
fn same<T:Serialize>(a:&T,b:&T)->bool{serde_json::to_value(a).unwrap()==serde_json::to_value(b).unwrap()}
fn region()->TargetSlotSpec{target(Zone::Region,EntityKind::Any,Relation::Any,Range::Anywhere)}
fn host()->TargetSlotSpec{let mut t=target(Zone::Board,EntityKind::Attachment,Relation::FriendlyTeam,Range::Anywhere);t.predicate=Some(TargetPredicate::BQ088Industry);t}
fn program(limit:Option<u32>,round:u32)->Vec<Op>{vec![Op::BQ088(Program::Start{limit,round}),Op::BQ088(Program::Mill),Op::BQ088(Program::Generate),Op::BQ088(Program::Seal),Op::BQ088(Program::Repeat)]}
pub(crate) fn definition(id:&str)->Definition{if id==TOKEN{let mut d=with_abilities(vec![]);d.traits.slow=true;return d;}let mut a=ability(KEY,"生化泄露：置顶入墓、生成行尸，可选封印及重复",Timing::Standard,vec![],vec![],vec![],None);a.play_only=true;a.modes=[("generate","生成行尸，不选择封印宿主",vec![region()]),("seal","生成行尸，可选封印至目标产业",vec![region(),host()])].into_iter().map(|(key,label,targets)|Mode{key:key.into(),label:label.into(),targets,ops:program(None,0)}).collect();with_abilities(vec![a])}
fn owns(o:&Op)->bool{match o{Op::BQ088(_)=>true,Op::ForEachLivingPlayer(v)|Op::ForEachLivingPlayerFromActor(v)=>v.iter().any(owns),Op::IfTargetExhausted{exhausted,ready,..}=>owns(exhausted)||owns(ready),_=>false}}
pub(crate) fn related(a:&AbilitySpec)->bool{a.key.starts_with("bq088-")||a.ops.iter().chain(a.modes.iter().flat_map(|m|&m.ops)).any(owns)}
fn related_frame(f:&ResolutionFrame)->bool{f.source.card.definition==ID||f.ability_key.starts_with("bq088-")||f.steps.iter().any(|s|owns(&s.op))}
pub(crate) fn validate_ability(id:&str,a:&AbilitySpec)->RuleResult<()>{let d=definition(ID);let base=&d.abilities[0];let valid=same(base,a)||base.modes.iter().any(|m|{let mut b=base.clone();b.targets=m.targets.clone();b.ops=m.ops.clone();b.modes.clear();same(&b,a)});if id!=ID||!valid{return Err("生化泄露须保留原目标和完整程序".into());}Ok(())}
pub(crate) fn validate_definition(id:&str,d:&Definition)->RuleResult<()>{if(matches!(id,ID|TOKEN)||d.abilities.iter().any(related))&&(!matches!(id,ID|TOKEN)||!same(d,&definition(id))){return Err("生化泄露/行尸完整定义不可移植或删改".into());}Ok(())}
impl Game {
 pub(crate) fn bq088_host(&self,actor:usize,c:&Card)->bool{!c.face_down&&self.team(actor)==self.team(c.controller)&&catalog::card(&c.definition).subtitle.as_deref()==Some("圣甲虫产业")&&self.attachments.iter().any(|a|a.card.id==c.id&&self.attachment_host_valid(a))&&self.seal_host_valid(&c.id)}
 pub(crate) fn bq088_candidates(&self,actor:usize,c:&Card)->Vec<(Action,String)>{let s=self.source_snapshot(c,None);let hosts=self.attachments.iter().filter(|a|self.valid_binding(actor,&s,&host(),&a.card.id)).map(|a|a.card.id.clone()).collect::<Vec<_>>();let mut out=vec![];for r in 0..self.regions.len(){if !self.valid_binding(actor,&s,&region(),&format!("region:{r}")){continue;}for h in std::iter::once(None).chain(hosts.iter().map(|h|Some(h.clone()))){let a=Action{card_id:Some(c.id.clone()),ability_id:Some(KEY.into()),region:Some(r),option:Some(if h.is_some(){"seal"}else{"generate"}.into()),target_id:h.clone(),..Action::new("play")};out.push((a,format!("生化泄露 · 地区{} · {}",r+1,h.unwrap_or("不封印".into()))));}}out}
 pub(crate) fn bq088_bind(&self,actor:usize,s:&SourceSnapshot,a:&Action)->RuleResult<Vec<BoundTarget>>{let seal=a.option.as_deref()==Some("seal");let expected=Action{card_id:a.card_id.clone(),ability_id:a.ability_id.clone(),region:a.region,option:a.option.clone(),target_id:if seal{a.target_id.clone()}else{None},..Action::new("play")};if *a!=expected||!matches!(a.option.as_deref(),Some("generate"|"seal"))||a.ability_id.as_deref().is_some_and(|k|k!=KEY){return Err("生化泄露须在支付前声明原地区和可选宿主".into());}let r=a.region.filter(|r|*r<self.regions.len()).ok_or("缺少目标地区")?;let mut out=vec![];for (t,id) in std::iter::once((region(),format!("region:{r}"))).chain(if seal{vec![(host(),a.target_id.clone().ok_or("缺少产业目标")?)]}else{vec![]}){if !self.valid_binding(actor,s,&t,&id){return Err("生化泄露目标不合法".into());}out.push(BoundTarget{public:self.public_target(actor,s,&t,&id),region_instance:if t.zone==Zone::Region{Some(self.regions[r].card.id.clone())}else{None},id,spec:t});}Ok(out)}
 pub(crate) fn validate_bq088_frame(&self,f:&ResolutionFrame)->RuleResult<()>{if !related_frame(f){return Ok(());}self.validate_resource_frame(f)?;let s=&f.source;let c=&s.card;
 if c.definition!=ID||f.actor>=self.players.len()||c.owner>=self.players.len()||c.controller!=f.actor||c.face_down||f.ability_key!=KEY||s.region.is_some()||s.source_region_instance.is_some()||s.play_source.is_some()||s.attachment_host_instance.is_some()||s.death_echo.is_some()||s.observed_death.is_some()||s.observed_exposure.is_some()||s.observed_mobility_grant.is_some()||!self.mystic_instance_number(&c.id).zip(self.mystic_instance_number(&f.frame_id)).is_some_and(|(a,b)|a<b)||!matches!(f.already_paid.as_slice(),[PaidCost::Assets(ids)]if f.money_units(0)<=1&&ids.iter().collect::<BTreeSet<_>>().len()==ids.len()&&ids.iter().all(|id|id!=&c.id&&self.mystic_instance_valid(id))){return Err("生化泄露来源或支付损坏".into());}
 let Some(Step{op:Op::BQ088(Program::Start{limit,round}),..})=f.steps.first()else{return Err("生化泄露缺少有限进度".into());};let expected=program(*limit,*round).into_iter().map(|op|Step{context:f.actor,op}).collect::<Vec<_>>();if !same(&f.steps,&expected)||!(1..=2).contains(&f.targets.len()){return Err("生化泄露程序或目标数量损坏".into());}let r=f.chosen_region.filter(|r|*r<self.regions.len()).ok_or("缺少原地区")?;for(i,t)in f.targets.iter().enumerate(){if !same(&t.spec,&if i==0{region()}else{host()})||t.public.instance_id!=t.id||!t.public.valid||t.public.status!="valid"||t.public.invalid_reason.is_some()||i==0&&(t.id!=format!("region:{r}")||t.public.kind!="region"||t.public.region!=Some(r)||t.region_instance.as_deref().is_none_or(|id|!self.mystic_instance_valid(id)))||i==1&&(!self.mystic_instance_valid(&t.id)||t.region_instance.is_some()){return Err("生化泄露原目标绑定损坏".into());}}
 match limit{None=>if *round!=0||f.cursor!=0||!matches!(f.guard,GuardState::Unchecked)||self.bq088_continuations.iter().any(|r|r.frame.frame_id==f.frame_id){return Err("生化泄露未开始帧已有进度".into());},Some(limit)=>{if *round>*limit||!(1..=5).contains(&f.cursor)||!matches!(f.guard,GuardState::Accepted)||!self.bq088_continuations.iter().any(|r|r.turn==self.turn&&same(&r.frame,f)){return Err("生化泄露有限进度或原续体损坏".into());}}}self.mobility_immutable_identity(c)
 }
 fn bq088_update(&mut self,f:&ResolutionFrame)->RuleResult<()>{let mut previous=f.clone();previous.cursor=previous.cursor.checked_sub(1).ok_or("缺少已执行游标")?;self.validate_bq088_frame(&previous)?;let r=self.bq088_continuations.iter_mut().find(|r|r.frame.frame_id==f.frame_id).ok_or("缺少生化泄露续体")?;r.frame=f.clone();Ok(())}
 fn bq088_done(&mut self,f:&ResolutionFrame){self.bq088_continuations.retain(|r|r.frame.frame_id!=f.frame_id);}
 pub(crate) fn bq088_start(&mut self,mut f:ResolutionFrame)->RuleResult<()>{let mut original=f.clone();original.cursor=0;original.guard=GuardState::Unchecked;self.validate_bq088_frame(&original)?;if f.cursor!=1||!matches!(f.guard,GuardState::Accepted){return Err("生化泄露须经目标守卫".into());}f.steps[0].op=Op::BQ088(Program::Start{limit:Some(self.players[f.actor].society_zone.secrecy),round:0});self.bq088_continuations.push(Continuation{turn:self.turn,frame:f.clone()});self.resolve_frame(f)}
 pub(crate) fn bq088_step(&mut self,f:&ResolutionFrame)->RuleResult<()>{self.bq088_update(f)?;match f.cursor{2=>self.mill_cards_with_cause(f.actor,1,Some(f))?,3=>{let r=f.chosen_region.unwrap();if !self.players[f.actor].eliminated&&self.region_live(r)&&f.targets[0].region_instance.as_ref()==Some(&self.regions[r].card.id){let c=self.make_generated(crate::generated::GeneratedKind::Walker,f.actor)?;let id=c.id.clone();self.regions[r].cards.push(c);self.enter_triggers(f.actor,TOKEN,&id,false);}},_=>return Err("生化泄露执行阶段损坏".into())}Ok(())}
 fn bq088_options(&self,f:&ResolutionFrame)->Vec<ChoiceOption>{if f.cursor==5{return vec![ChoiceOption{id:"repeat".into(),label:"再执行一次生化泄露".into(),card:None}];}let Some(h)=f.targets.get(1)else{return vec![];};if !self.valid_bound_target(f.actor,&f.source,h){return vec![];}self.players.iter().filter(|p|self.team(p.seat)==self.team(f.actor)).flat_map(|p|p.graveyard.iter().filter(|c|catalog::card(&c.definition).name=="无名尸体").map(|c|self.option(c,p.seat,None,None))).collect()}
 pub(crate) fn bq088_wait(&mut self,f:ResolutionFrame)->RuleResult<()>{self.bq088_update(&f)?;let Op::BQ088(Program::Start{limit:Some(limit),round})=f.steps[0].op else{return Err("生化泄露重复上限丢失".into());};if self.players[f.actor].eliminated||f.cursor==5&&round>=limit{self.bq088_done(&f);return Ok(());}let options=self.bq088_options(&f);if options.is_empty(){return self.resolve_frame(f);}let repeat=f.cursor==5;self.choice(f.actor,if repeat{"bq088-repeat"}else{"bq088-seal"},if repeat{"生化泄露：可以再执行一次"}else{"生化泄露：可以封印一张本方无名尸体"}.into(),options,0,1,None,ChoiceResolution::Frame{frame:Box::new(f),choice:FrameChoice::BQ088{repeat}});Ok(())}
 pub(crate) fn bq088_choose(&mut self,mut f:ResolutionFrame,repeat:bool,seat:usize,a:&Action,selected:&[String])->RuleResult<()>{self.validate_bq088_frame(&f)?;if seat!=f.actor||f.cursor!=if repeat{5}else{4}||selected.len()>1||*a!=(Action{choice_id:a.choice_id.clone(),selected:a.selected.clone(),..Action::new("choose")})||selected.iter().any(|id|!self.bq088_options(&f).iter().any(|o|&o.id==id)){return Err("生化泄露选择或原阶段不符".into());}if repeat{let Op::BQ088(Program::Start{limit:Some(limit),round})=f.steps[0].op else{return Err("重复上限损坏".into());};if selected.is_empty()||round>=limit||f.targets.iter().any(|t|!self.valid_bound_target(f.actor,&f.source,t)){self.bq088_done(&f);return Ok(());}f.steps[0].op=Op::BQ088(Program::Start{limit:Some(limit),round:round+1});f.cursor=1;self.bq088_continuations.iter_mut().find(|r|r.frame.frame_id==f.frame_id).unwrap().frame=f.clone();}else if let Some(id)=selected.first(){let p=self.players.iter().position(|p|p.graveyard.iter().any(|c|&c.id==id)).ok_or("尸体已离开墓地")?;let i=self.players[p].graveyard.iter().position(|c|&c.id==id).unwrap();let c=self.take_grave_observed(p,i);self.seal_card_on_valid_host(c,f.actor,&f.targets[1].id);}self.resolve_frame(f)}
 pub(crate) fn validate_bq088_play(&self,i:&StackItem)->RuleResult<()>{if i.card.as_ref().is_some_and(|c|c.definition==ID)||i.frame.as_ref().is_some_and(related_frame){let f=i.frame.as_ref().ok_or("生化泄露实际事务缺帧")?;self.validate_bq088_frame(f)?;if f.cursor!=0||i.id!=f.frame_id||i.controller!=f.actor||i.reveal||i.deploy_region.is_some()||i.target.as_deref()!=f.targets.first().map(|t|t.id.as_str())||i.card.as_ref().is_none_or(|c|!self.pack_a_transaction_matches(f,c)){return Err("生化泄露实际事务与原帧不符".into());}}Ok(())}
 pub(crate) fn validate_bq088_state(&self)->RuleResult<()>{let mut records=BTreeSet::new();for r in &self.bq088_continuations{self.validate_bq088_frame(&r.frame)?;if !records.insert(r.frame.frame_id.clone()){return Err("重复生化泄露进度".into());}}let mut seen=BTreeSet::new();let mut carriers=BTreeSet::new();let mut check=|f:&ResolutionFrame|->RuleResult<()>{self.validate_bq088_frame(f)?;if related_frame(f){if !seen.insert(f.frame_id.clone()){return Err("生化泄露同帧重复载体".into());}if f.cursor>0{carriers.insert(f.frame_id.clone());}}Ok(())};for i in &self.stack{self.validate_bq088_play(i)?;self.validate_bq088_token_play(i)?;if let Some(f)=&i.frame{if f.source.card.definition==TOKEN&&f.ability_key!="reveal"&&!self.validated_mobility_frame(f)?{return Err("行尸不能借用其他角色能力帧".into());}check(f)?;}}for e in &self.effects{match e{Effect::Frame{frame}=>check(frame)?,Effect::DeathCaller{caller}=>check(&caller.frame)?,Effect::Declare{declaration:d}if d.source.card.definition==ID||related(&d.ability)=>return Err("生化泄露没有触发声明".into()),_=>()}}if let Some(p)=&self.pending{match &p.resolution{ChoiceResolution::Frame{frame:f,choice}if related_frame(f)||matches!(choice,FrameChoice::BQ088{..})=>{if f.source.card.definition!=ID{return Err("生化泄露待选不能移植来源".into());}check(f)?;let FrameChoice::BQ088{repeat}=choice else{return Err("生化泄露选择阶段被替换".into());};if *repeat&&!matches!(f.steps[0].op,Op::BQ088(Program::Start{limit:Some(limit),round})if round<limit){return Err("已达重复上限不能仍有待选".into());}let expected=Choice{id:p.choice.id.clone(),kind:if *repeat{"bq088-repeat"}else{"bq088-seal"}.into(),title:if *repeat{"生化泄露：可以再执行一次"}else{"生化泄露：可以封印一张本方无名尸体"}.into(),description:"选择符合数量限制的选项，然后确认。".into(),player_id:player_id(f.actor),options:self.bq088_options(f),preview_cards:vec![],min:Some(0),max:Some(1),amount:None,allow_decline:Some(true)};if p.seat!=f.actor||!self.mystic_instance_valid(&p.choice.id)||f.cursor!=if *repeat{5}else{4}||expected.options.is_empty()||!same(&p.choice,&expected){return Err("生化泄露选择选项或原阶段损坏".into());}},ChoiceResolution::Declare{declaration:d,..}if d.source.card.definition==ID||related(&d.ability)=>return Err("生化泄露没有声明待选".into()),_=>()}}if records!=carriers{return Err("生化泄露每条进度须有且只有一个实际续体".into());}Ok(())}
}

impl Game {
 pub(crate) fn validate_bq088_token_play(&self,item:&StackItem)->RuleResult<()>{
  if !item.card.as_ref().is_some_and(|c|matches!(c.definition.as_str(),TOKEN))&&!item.frame.as_ref().is_some_and(|f|matches!(f.source.card.definition.as_str(),TOKEN)&&matches!(f.ability_key.as_str(),"deploy"|"reveal")){return Ok(());}
  let f=item.frame.as_ref().ok_or("TK001角色事务缺少原帧")?;let c=&f.source.card;
  if !matches!(c.definition.as_str(),TOKEN)||f.actor>=self.players.len()||c.owner>=self.players.len()||c.controller!=f.actor||!self.mystic_instance_valid(&c.id)||!self.mystic_instance_valid(&f.frame_id)
   ||f.source.region.is_none_or(|r|r>=self.regions.len())||f.source.source_region_instance.as_deref().is_none_or(|id|!self.mystic_instance_valid(id))
   ||f.source.attachment_host_instance.is_some()||f.source.death_echo.is_some()||f.source.observed_death.is_some()||f.source.observed_exposure.is_some()||f.source.observed_mobility_grant.is_some()
   ||f.cursor!=0||!matches!(f.guard,GuardState::Unchecked)||!f.steps.is_empty()||!f.targets.is_empty()||f.chosen_region!=f.source.region
   ||!matches!(f.ability_key.as_str(),"deploy"|"reveal")||f.ability_key=="deploy"&&(c.face_down||!f.source.valid_character_play())||f.ability_key=="reveal"&&(!c.face_down||f.source.play_source.is_some())
   ||!matches!(f.already_paid.as_slice(),[PaidCost::Assets(ids)] if f.money_units(0)<=8&&ids.iter().all(|id|self.mystic_instance_valid(id)&&*id!=c.id)&&ids.iter().collect::<BTreeSet<_>>().len()==ids.len())
   ||item.id!=f.frame_id||item.controller!=f.actor||item.target.is_some()||item.reveal!=(f.ability_key=="reveal")||item.deploy_region!=f.source.region
   ||item.card.as_ref().is_none_or(|c|!self.pack_a_transaction_matches(f,c)){return Err("TK001角色事务、原帧或实际牌面不符".into());}if (f.ability_key!="reveal" || f.money_units(0)!=0 || !f.resource_payments.is_empty() || !matches!(f.already_paid.as_slice(),[PaidCost::Assets(ids)] if ids.is_empty())) {return Err("行尸只接受真实零费现身事务".into());} self.validate_generated_identity(c)?;self.mobility_immutable_identity(c)
 }
}
